properties.query:
let winrm_events = SecurityEvent | where EventID == 4624 and AuthenticationPackageName == "Negotiate" and ProcessName has "winrm" | summarize winrm_time=min(TimeGenerated) by TargetUserName, Computer;
let ps_events = SecurityEvent | where EventID == 4103 and ScriptBlockText has_any ("Get-ADDomainController", "Get-ADUser", "Invoke-Command") | summarize ps_time=min(TimeGenerated) by TargetUserName, Computer;
winrm_events | join kind=inner ps_events on TargetUserName | where ps_time - winrm_time between (0min .. 30min)
